/* The Planner — Act I: The Making (1887–1924).
   Spine (Dalton, here Hugh Dalby's place): Windsor, the royal chaplain's son; Eton and Chambers's tariffs;
   King's, the Fabians and Rupert Brooke; the LSE and the Webbers; the artillery in Italy and Caporetto;
   the lost elections of 1922–24 and Peckham in 1924.
   Fork, "After school" (1906), per docs/camps/planner.md:
     route-kings    (historical) the Dalby spine.
     route-patents  Crisp: UCL chemistry, the Red Cross in France, the munitions works, the patent Bar.
     route-wea      the WEA tutor: teaching miners from 1908 (Gaskell and Dunbar later, Act II).
     route-grammar  Wilmot: the route follows a younger life, born 1916 (`born=1916 year=1930`): the father
                    out of work, the Wirral, Jesus College, a First. Rejoins at the 1945 election.
   Rogue fork: none in Act I but `fork=shellshock17` (Caporetto, a breakdown that ends the life's politics).
   Sources: RESEARCH.md, "Planner figures, re-read 11 Nov 2026". */
(function () {
  const TM = (window.TM = window.TM || {});
  TM.ACTS = TM.ACTS || {};
  TM.ACTS.planner = TM.ACTS.planner || {};

  TM.PEOPLE = Object.assign(TM.PEOPLE || {}, {
    brooke: { name: 'Rupert Brooke', role: 'A golden young poet at King\'s' },
    webber: { name: 'Beatrice and Sidney Webber', role: 'The Fabian partnership' },
    crisp: { name: 'Stafford Crisp', role: 'A rich young chemist and barrister' },
    tawney: { name: 'Mr Tawney', role: 'A WEA tutor with a pipe and a conscience' },
    ruth: { name: 'Ruth', role: 'An LSE student; later your wife' },
    hendry: { name: 'Mr Arthur Hendry', role: 'Labour\'s party manager' },
    mary: { name: 'Mary', role: 'A clerk\'s daughter who writes poetry' },
  });

  TM.VARDEF = Object.assign(TM.VARDEF || {}, { planner: { seat: 'Peckham', party: 'Labour', city: 'London', town: 'Windsor' } });
  const PLAN = TM.PLAN_SPINE = '~!route-patents ~!route-wea ~!route-grammar';

  TM.FORKS = TM.FORKS || {};
  TM.FORKS.shellshock17 = {
    title: 'After Caporetto',
    history: 'In the retreat from Caporetto in November 1917 a young British artillery officer brought his guns back across the Tagliamento and then, a week later, could not stop shaking. He was invalided home and spent most of 1918 in a hospital for officers with nerves. He never stood for Parliament. In the 1920s he taught economics at a provincial university and wrote one good book on public finance that the Treasury read and ignored.',
    more: [],
    real: 'Hugh Dalton served with the Royal Artillery on the Italian front, was decorated by the Italians for his conduct in the Caporetto retreat, wrote a memoir of the campaign, and went on to the LSE and Parliament.',
    ends: { 1: { head: 'The lecturer', text: '1924. {first} {last} is {age}, a lecturer in economics in the provinces, sleeping badly, writing well, and watching other men go into politics.' } },
  };

  TM.ACTS.planner[1] = {
    title: 'Act I · The Making',
    span: '1887–1924',
    regen: 3,
    continues: 'Acts II and III of this life are still being written, so this life ends here for now.',
    intro: 'You were born in August 1887 at Neath, in South Wales, but you have grown up in the cloisters of Windsor Castle. Your father is a canon of St George\'s Chapel, a royal chaplain who once tutored the Queen\'s grandsons, and a Tory who speaks his mind. The Prince of Wales calls at the house. You are loud, clever, clumsy and ten years old, and you assume that the world will listen.',
    end: (s) => {
      const age = s.year - s.born;
      if (s.flags.includes('route-grammar')) return { head: 'A First', text: '1937. {first} {last} is ' + age + ', with a First from Oxford, no money, and a head full of statistics. The war that is coming will need people who can count.' };
      if (s.flags.includes('mp')) return { head: 'The Member for {seat}', text: '1924. {first} {last} is ' + age + ', the Labour Member for {seat}, a doctor of economics with a booming voice and a canon\'s son on the red benches. The old guard think he is a class traitor; the new guard think he is a toff.' };
      if (s.flags.includes('route-patents')) return { head: 'The patent Bar', text: '1924. {first} {last} is ' + age + ', the cleverest patent barrister in London and richer every year, a churchman and a Liberal of sorts, with no idea yet that the Labour Party will want him.' };
      if (s.flags.includes('route-wea')) return { head: 'The tutor', text: '1924. {first} {last} is ' + age + ', a tutor to miners and weavers, owed favours by half the union lodges in the Midlands, and still not in Parliament.' };
      return { head: 'Not yet', text: '1924. {first} {last} is ' + age + ', a lecturer at the London School of Economics with a doctorate and four lost elections. The fifth will come.' };
    },
    start: {
      born: 1887,
      year: 1897,
      effects: 'cap+4 money+10 fav+4',
      rel: {
        father: { name: 'Your father', role: 'Canon of Windsor, royal tutor, Tory', score: 40, status: 'Loud, proud, impossible to please.' },
        mother: { name: 'Your mother', role: 'A canon\'s wife', score: 60, status: 'Fond of you, wary of your father.' },
      },
    },

    scenes: [
      /* ═══════ Everyday politics of a Windsor boyhood ═══════ */
      { id: 'jubilee-1897', year: 1897, title: 'The Diamond Jubilee',
        venue: { plate: 'city', label: 'The cloisters, Windsor Castle' },
        text: 'June 1897. Sixty years of the Queen. Every house in Windsor has bunting and the troops of the Empire are marching through London: Sikhs, Maoris, Canadian Mounties. Your father has a seat at St Paul\'s. You are left at home with the Dean\'s sons, who plan to climb the Round Tower to see the bonfires. The verger has said the Tower is out of bounds tonight.',
        basis: 'Queen Victoria\'s Diamond Jubilee, 22 June 1897; Dalton\'s childhood at Windsor, where his father was a canon of St George\'s Chapel.',
        real: 'The Diamond Jubilee procession on 22 June 1897 was a parade of imperial troops through London; bonfires were lit across the country. Hugh Dalton grew up at Windsor, where his father, John Neale Dalton, was a canon. The details of this scene are invented.',
        check: 'research', facts: ['dalton-early'],
        choices: [
          { label: 'Climb the Tower', effects: 'temper+2 steel+1 health-1', historical: true,
            roll: { stat: 'health', diff: 30,
              pass: { effects: 'press+1', result: 'From the top you count forty bonfires on the hills. Nobody catches you. You decide that rules are for people without imagination.', diary: 'Forty bonfires from the Round Tower.' },
              fail: { effects: '@father-5', result: 'The verger catches you on the stair. Your father canes you, then asks how many bonfires there were.', diary: 'Caught. Caned. He asked how many.' } } },
          { label: 'Stay and read about the Empire', effects: 'empire+2 cap+1',
            result: 'You read the Jubilee number of the Illustrated London News from end to end: so many places painted red.',
            diary: 'The map is very red.' },
          { label: 'Go to the town and watch the crowds', effects: 'order-1 state+1',
            result: 'In Peascod Street the beer flows and a man in a cloth cap tells you his wages have not risen in ten years. You had not known that.',
            diary: 'Peascod Street. Wages.' },
        ] },

      { id: 'mafeking-1900', year: 1900, title: 'Mafeking night',
        venue: { plate: 'school', label: 'Summer Fields, Oxford' },
        text: 'May 1900. Mafeking has been relieved after seven months, and the whole school is let out to cheer. Boys set fire to an effigy of President Kruger. A master who has said the war is wrong is being hooted in the corridor. You have read in your father\'s papers that the Boers are farmers defending their land. Everyone else is singing Soldiers of the Queen.',
        basis: 'The relief of Mafeking, 17 May 1900, and the celebrations of 18–19 May; Dalton attended Summer Fields preparatory school before Eton.',
        real: 'News of the relief of Mafeking reached London on 18 May 1900 and set off wild celebrations. Dalton was at Summer Fields in Oxford before going to Eton. The master and the effigy are invented.',
        check: 'research', facts: ['dalton-early', 'mafeking-1900'],
        choices: [
          { label: 'Cheer with the rest', effects: 'empire+2 loyalty+2', historical: true,
            result: 'You cheer until you are hoarse. It feels wonderful to be on the winning side.',
            diary: 'Cheered until hoarse.' },
          { label: 'Stand by the master', effects: 'empire-2 steel+2 @father-2',
            result: 'You walk beside him to the staff room. The other boys call you a pro-Boer for a term. You find you rather like it.',
            diary: 'Walked with the master. Pro-Boer, they call me.' },
          { label: 'Argue the Boer case in the dormitory', effects: 'empire-1 cap+2 temper+2',
            result: 'You lose the argument and win a pillow fight. Two boys come round, privately.',
            diary: 'Lost the argument. Two came round.' },
        ] },

      { id: 'funeral-1901', year: 1901, title: 'The Queen comes home',
        venue: { plate: 'city', label: 'St George\'s Chapel, Windsor' },
        text: 'February 1901. The old Queen is dead, and her coffin comes to Windsor on a gun carriage. The horses of the artillery bolt in the cold, and the sailors of the guard of honour haul the gun carriage up the hill themselves. Your father is in the chapel in his robes. The new King nods to him. You are thirteen, in the crowd, and you notice who is crying and who is counting.',
        basis: 'Queen Victoria\'s funeral at Windsor on 2 February 1901, when the horses bolted and naval ratings drew the gun carriage; Canon Dalton had tutored the new King\'s sons and was a friend of the royal household.',
        real: 'At Windsor on 2 February 1901 the artillery horses drawing the Queen\'s coffin bolted, and naval ratings pulled the gun carriage to St George\'s Chapel, beginning a tradition. Canon Dalton served at St George\'s.',
        check: 'unchecked', facts: ['dalton-early', 'funeral-1901'],
        choices: [
          { label: 'Watch the King, and the men round him', effects: 'cap+2 order+1', historical: true,
            result: 'You see which ministers stand near him and which are kept at the back. It is your first lesson in politics, and you never forget it.',
            diary: 'Who stood near the King.' },
          { label: 'Help the sailors at the ropes', effects: 'state+1 steel+1 press+1',
            result: 'A petty officer lets you take a rope for the last few yards. A newspaper artist sketches the scene; you are a blur in the corner.',
            diary: 'Held a rope. A blur in the Graphic.' },
          { label: 'Ask your father what a king is for', effects: 'order-2 @father-3',
            result: 'He tells you to hold your tongue. Later he tells you, at length. You are not persuaded.',
            diary: 'What is a king for? Not persuaded.' },
        ] },

      { id: 'tariffs-1903', year: 1903, title: 'Mr Chambers\'s tariffs',
        venue: { plate: 'harrow', label: 'The Eton Society, Eton College' },
        text: 'November 1903. Mr Joseph Chambers has resigned from the Cabinet to campaign for tariffs on foreign goods and preference for the Empire. At Eton the debating society takes a vote. You admire Chambers: he wants to use the State to make the country strong, and to pay for pensions with the tariff. The Free Traders say it means dear bread for the poor. You are to speak first.',
        basis: 'Joseph Chamberlain\'s tariff reform campaign from 1903; Dalton at Eton was, by his own later account, an admirer of Chamberlain before he turned to socialism at Cambridge.',
        real: 'Joseph Chamberlain resigned from the Cabinet in September 1903 to campaign for tariff reform and imperial preference. Pimlott records that Dalton moved from Chamberlain to Keir Hardie and the Webbs as he grew up. The debate is invented.',
        check: 'research', facts: ['dalton-early', 'tariff-reform'],
        choices: [
          { label: 'Speak for Chambers: a strong State for a strong Empire', effects: 'state+2 empire+2 press+1', historical: true,
            result: 'You carry the house by eleven votes. A master says you have a voice like a foghorn and the nerve to match.',
            diary: 'Carried it by eleven. Foghorn, he said.' },
          { label: 'Speak for Free Trade and cheap bread', effects: 'order-2 state-1 cap+1',
            result: 'You lose, but a boy from a Liberal family asks you to tea.',
            diary: 'Lost. Tea with a Liberal.' },
          { label: 'Say both sides forget the poor', effects: 'state+3 order-2 temper+1',
            result: 'The house laughs at you. You go away and read a pamphlet by the Fabian Society that a scholar lent you.',
            diary: 'They laughed. The Fabian pamphlet.' },
        ] },

      { id: 'neath-1904', year: 1904, title: 'The valley you were born in',
        venue: { plate: 'mill', label: 'The Vale of Neath' },
        text: 'August 1904. A summer visit to Neath, where you were born and remember nothing. Your mother\'s cousin takes you down a colliery: a mile of tunnel, two feet of seam, boys younger than you on their knees with a candle. On the way up the manager says the men are well paid and drink it. In the chapel that night a revivalist preacher makes grown colliers weep. Nobody weeps for the boys.',
        basis: 'Dalton\'s birth at Neath in 1887; the South Wales coalfield in 1904, the year of the Welsh Revival.',
        real: 'Hugh Dalton was born at Neath, Glamorgan, in 1887. The Welsh Revival of 1904–05 swept the mining valleys. The visit is invented; it stands for the experience of poverty that turned a number of upper-class young men to socialism.',
        check: 'research', facts: ['dalton-early'],
        choices: [
          { label: 'Ask the boys what they earn', effects: 'state+3 order-2', historical: true,
            result: 'One of them tells you: tenpence a day. He asks what you earn. You have never earned anything.',
            diary: 'Tenpence a day. I have never earned anything.' },
          { label: 'Ask the manager about the profits', effects: 'cap+2 state+1',
            result: 'He is amused and shows you the books. The figures are very good, for the owners.',
            diary: 'The books. Good figures, for some.' },
          { label: 'Go to the chapel and listen', effects: 'order+1 health+1',
            result: 'The singing goes on until midnight. You do not believe it, and you envy those who do.',
            diary: 'The singing. I envy them.' },
        ] },

      /* ═══════ The fork ═══════ */
      { id: 'after-school-1906', year: 1906, title: 'After school',
        venue: { plate: 'harrow', label: 'Your study, Eton College' },
        text: 'Summer 1906. The Liberals have won a landslide and twenty-nine Labour men sit in the Commons. Your schooldays are over. Your father expects King\'s, Cambridge, and the Church or the Bar. A cousin in chemistry says science and patents are where the money and the future lie. A clergyman you met at a settlement in the East End says the real university is a class of working men on a winter night.',
        basis: 'A fork invented for the camp (docs/camps/planner.md). Dalton went up to King\'s in 1906; Cripps read chemistry at UCL; R. H. Tawney began teaching WEA tutorial classes in 1908; Harold Wilson, the fourth route, was born in 1916.',
        real: 'Hugh Dalton went up to King\'s College, Cambridge, in 1906 and became a socialist there. Stafford Cripps read chemistry at University College London. Hugh Gaitskell and Evan Durbin taught adult classes for the Workers\' Educational Association. Harold Wilson was born in Huddersfield in 1916.',
        check: 'research', facts: ['dalton-early', 'cripps-early', 'wilson-early'],
        choices: [
          { label: 'King\'s, Cambridge', effects: 'cap+3 fav+2 !route-kings', historical: true,
            result: 'You go up to King\'s in October. On the first evening a young man with golden hair and a book of poems asks you to his rooms.',
            diary: 'King\'s. The golden boy with the poems.' },
          { label: 'Chemistry in London, and the family money', effects: 'cap+3 money+10 order+2 !route-patents set:seat=Bristol_East set:town=London',
            result: 'You enrol at University College London to read chemistry under a great professor. Your father calls it trade. Your bank manager calls it sense.',
            diary: 'Chemistry at UCL. Trade, says father.' },
          { label: 'Teach working men for the WEA', effects: 'state+3 cap+1 money-5 @father-6 !route-wea set:seat=Leeds_South set:town=Nottingham',
            result: 'You take a shabby room in the Potteries and a class of twenty miners and potters, three evenings a week, who know more than you about almost everything.',
            diary: 'The Potteries. Twenty men who know more than me.' },
          { label: 'Another life: a Huddersfield chemist\'s son, born in 1916', effects: 'born=1916 year=1930 money-20 fav-6 cap-4 !route-grammar set:seat=Ormskirk set:town=Huddersfield',
            result: 'The story follows a younger life instead: a boy born in Huddersfield in 1916, clever, tidy, with a pipe he does not yet smoke. It is December 1930 and his father has just lost his job.',
            diary: 'A different life: Huddersfield, 1930.' },
        ] },

      /* ═══════ King's: the Dalby spine ═══════ */
      { id: 'fabians-1907', year: 1907, title: 'Comrade Hugh', if: PLAN,
        venue: { plate: 'school', label: 'The Cambridge University Fabian Society, King\'s' },
        text: 'November 1907. You have read the Fabian Essays and Mr Webber\'s pamphlets and you have stopped believing in Mr Chambers. You call yourself a socialist in hall, loudly, and the college calls you Comrade Hugh. The University Fabians want you as their president. The Union, where careers begin, wants you as its secretary, if you will tone it down. Both elections are next week.',
        basis: 'Dalton at King\'s: a convert to socialism, nicknamed "Comrade Hugh", president of the Cambridge University Fabian Society; he failed three times to be elected secretary of the Cambridge Union.',
        real: 'At King\'s Dalton became a socialist and president of the University Fabian Society, and was known as "Comrade Hugh". He stood three times for secretary of the Cambridge Union and lost each time.',
        check: 'research', facts: ['dalton-early'],
        choices: [
          { label: 'Take the Fabians and stay loud', effects: 'state+3 press+2 fav-2 @webber+3', historical: true,
            result: 'You win the Fabians and lose the Union. You will lose it twice more. The Fabians are better company.',
            diary: 'Fabians won. Union lost. Better company.' },
          { label: 'Tone it down and take the Union', effects: 'fav+3 loyalty+2 state-1',
            roll: { stat: 'favour', diff: 40,
              pass: { effects: 'cap+3', result: 'You are elected secretary. The dons begin to talk of you as a coming man.', diary: 'Union secretary. A coming man.' },
              fail: { effects: 'rep-1', result: 'You tone it down and lose anyway. Nobody believed the new voice.', diary: 'Toned down. Lost anyway.' } } },
          { label: 'Invite the Labour men from the valleys to speak', effects: 'state+2 temper+2 order-2',
            result: 'The Labour leader comes in his cloth cap. Undergraduates break up the meeting and throw him in the Cam. You pull him out.',
            diary: 'Pulled him out of the Cam.' },
        ] },

      { id: 'backs-1908', year: 1908, title: 'Walking on the Backs', if: PLAN,
        venue: { plate: 'embankment', label: 'The Backs, behind King\'s' },
        text: 'May 1908. Rupert Brooke, who is going to be the great poet of the age, walks with you along the river after hall. He wants you to give up politics for poetry, and to come to Grantchester and swim at night. He says the Fabians are dull and the Webbers have no souls. You say poetry will not feed a single child. He laughs and says that is why you love him.',
        basis: 'Dalton\'s friendship with Rupert Brooke at King\'s; both were Fabians; Dalton wrote in the 1950s that Brooke\'s memory still lit his path.',
        real: 'Rupert Brooke and Hugh Dalton were close friends at Cambridge and fellow Fabians. Dalton kept Brooke\'s memory all his life. The conversation is invented.',
        check: 'unchecked', facts: ['planner-brooke'],
        choices: [
          { label: 'Go to Grantchester', effects: 'health+3 @brooke+8 temper+1', historical: true,
            result: 'You swim in Byron\'s Pool at midnight and argue till dawn. It is the happiest summer of your life. You will remember it in a war.',
            diary: 'Byron\'s Pool at midnight.' },
          { label: 'Stay and write the Fabian report', effects: 'cap+3 state+2 @brooke-2',
            result: 'You write a paper on the incidence of taxation. Brooke reads it and writes a sonnet about how dull it is.',
            diary: 'Taxation. He wrote a sonnet about it.' },
          { label: 'Bring him to a Fabian summer school', effects: 'state+2 @brooke+4 @webber+2',
            result: 'He charms Mrs Webber and is bored by Mr Webber. He makes the summer school famous for a season.',
            diary: 'He charmed Mrs Webber.' },
        ] },

      { id: 'minority-report-1909', year: 1909, title: 'Break up the Poor Law', if: PLAN,
        venue: { plate: 'city', label: 'A Fabian meeting, Essex Hall, Strand' },
        text: '1909. The Royal Commission on the Poor Law has reported twice. The majority would keep the workhouse, mended. Mrs Webber\'s Minority Report would abolish it and put the sick, the old, the children and the unemployed each under a proper public service. She has started a national campaign to break up the Poor Law. She wants young men who can count, write and speak. You can do all three.',
        basis: 'The Minority Report of the Royal Commission on the Poor Laws (1909), drafted by Beatrice and Sidney Webb, and the National Committee for the Break-up of the Poor Law; Dalton\'s debt to the Webbs.',
        real: 'The Royal Commission on the Poor Laws reported in February 1909. Beatrice Webb\'s Minority Report proposed abolishing the Poor Law and replacing it with specialised public services; the Webbs ran a national campaign for it. It shaped the welfare state of the 1940s.',
        check: 'unchecked', facts: ['minority-report-1909', 'dalton-early'],
        choices: [
          { label: 'Join the campaign as a speaker', effects: 'state+3 press+2 @webber+5 health-1', historical: true,
            result: 'You speak in fifty church halls in a year. Mrs Webber says you are too pleased with yourself but very useful.',
            diary: 'Fifty halls. Too pleased, but useful.' },
          { label: 'Do the statistics for the campaign', effects: 'cap+4 state+2 @webber+3',
            result: 'You cost the Minority Report county by county. The figures are quoted in the Commons by a Liberal.',
            diary: 'Costed it. Quoted in the Commons.' },
          { label: 'Stay out: the Liberals will do it anyway', effects: 'order+1 fav+2',
            result: 'Mr Lloyd Gwynne\'s budget is more exciting anyway. You follow it like a horse race.',
            diary: 'Watched the budget instead.' },
        ] },

      { id: 'lse-1911', year: 1911, title: 'Clare Market', if: PLAN,
        venue: { plate: 'city', label: 'The London School of Economics, Clare Market' },
        text: '1911. You have come down from Cambridge to the London School of Economics, which the Webbers founded, to study public finance, and to the Middle Temple, to keep terms for the Bar. Your father would prefer the Bar. The LSE is a warren of rooms above shops, full of Indians, Germans and women with short hair, and the talk is of the national insurance bill. A lecturer offers you research on taxation.',
        basis: 'Dalton\'s study at the London School of Economics and the Middle Temple after Cambridge; he later took a DSc on public finance and published The Principles of Public Finance (1922).',
        real: 'After Cambridge Dalton studied at the LSE and the Middle Temple and was called to the Bar. After the war he lectured at the LSE, took a doctorate on the inequality of incomes and wrote The Principles of Public Finance (1922).',
        check: 'research', facts: ['dalton-early'],
        choices: [
          { label: 'Take the research: taxation is where power lives', effects: 'cap+4 state+2', historical: true,
            result: 'You start counting who owns what in England. The answer is so unequal that you check it three times.',
            diary: 'Who owns England. Checked three times.' },
          { label: 'Concentrate on the Bar', effects: 'money+6 fav+2 order+1',
            result: 'You eat your dinners and learn the law. Your father is pleased. You are bored.',
            diary: 'Dinners at the Temple. Bored.' },
          { label: 'Fall in love', effects: 'health+3 temper+1 @ruth+10',
            result: 'Ruth Fox, an LSE student, sharp and plain-spoken, laughs at your voice and argues about Ricardo. You marry in 1914.',
            diary: 'Ruth. Ricardo. We will marry.' },
        ] },

      { id: 'brooke-1915', year: 1915, title: 'Skyros', if: PLAN,
        venue: { plate: 'sickroom', label: 'An Army Service Corps billet, France' },
        text: 'April 1915. You joined up in the first weeks, and the Army made you a transport officer, counting lorries and fodder. Today\'s Times, a week old, says Rupert Brooke has died on a hospital ship off Skyros on the way to Gallipoli, of a mosquito bite, and that the nation mourns its poet. You sit in the lorry park and cannot read the rest. A transfer to the artillery is on offer.',
        basis: 'Rupert Brooke\'s death on 23 April 1915 near Skyros; Dalton served in the Army Service Corps and transferred to the Royal Artillery in January 1917.',
        real: 'Rupert Brooke died of sepsis from an infected mosquito bite on 23 April 1915 on a French hospital ship off Skyros, and was buried on the island. Dalton served in the Army Service Corps before transferring to the Royal Artillery in January 1917.',
        check: 'unchecked', facts: ['planner-brooke', 'dalton-early'],
        choices: [
          { label: 'Apply for the guns', effects: 'steel+3 health-1', historical: true,
            result: 'The transfer takes nearly two years. When it comes, you are sent to a gunnery course and then to Italy.',
            diary: 'Applied for the guns. Italy.' },
          { label: 'Stay with the lorries, where you are useful', effects: 'cap+2 order+1',
            result: 'Your convoys are never late. You learn more about logistics than any economist alive.',
            diary: 'The convoys are never late.' },
          { label: 'Write about him', effects: 'press+2 @brooke+5',
            result: 'You write a memoir of Brooke at Cambridge for a college magazine. You keep his letters all your life.',
            diary: 'Wrote about him. I keep his letters.' },
        ] },

      { id: 'caporetto-1917', year: 1917, t: 1917.85, title: 'Caporetto', if: PLAN,
        venue: { plate: 'frontier', label: 'The Isonzo front, Italy' },
        text: 'October 1917. Your battery of heavy guns is on the Isonzo when the Austrians and Germans break through at Caporetto. The Italian Second Army is streaming back down the roads, throwing away rifles. Your orders are to withdraw the guns across the Tagliamento before the bridges go. The roads are jammed with carts and refugees. An Italian major begs you to leave the guns and save the men.',
        basis: 'Dalton\'s service as a lieutenant of the Royal Artillery on the Italian front; he received the Italian bronze medal for valour for his conduct in the retreat from Caporetto, and wrote With British Guns in Italy (1919).',
        real: 'The Austro-German offensive at Caporetto broke the Italian line on 24 October 1917 and drove the Italians back to the Piave. British batteries were caught in the retreat. Dalton was awarded the Italian bronze medal for valour and published With British Guns in Italy.',
        check: 'research', facts: ['dalton-early', 'caporetto-1917'],
        choices: [
          { label: 'Bring the guns back, whatever it takes', effects: 'steel+4 rep+3 health-3', historical: true,
            death: { chance: 0.05, text: 'You were killed on the road to the Tagliamento in November 1917, bringing back the guns, when an Austrian aircraft strafed the column.', headline: 'Killed at Caporetto' },
            roll: { stat: 'health', diff: 35,
              pass: { effects: 'rep+2 #italian-medal', result: 'You get the guns over the river an hour before the bridge is blown. The Italians give you a medal.', diary: 'Over the Tagliamento. A medal.' },
              fail: { effects: 'health-6 fork=shellshock17', result: 'You get the guns back, and a week later, on the Piave, you cannot stop shaking.', diary: 'Cannot stop shaking.' } } },
          { label: 'Spike the guns and save the men', effects: 'state+2 rep-1',
            result: 'You blow the breeches and march the men back. Not a man is lost. A court of inquiry clears you, grudgingly.',
            diary: 'Spiked the guns. Every man saved.' },
          { label: 'Use the guns to cover the Italian retreat', effects: 'steel+3 empire-1 rep+2 health-2',
            death: { chance: 0.06, text: 'You were killed in November 1917 on the Isonzo, firing over open sights to cover the Italian retreat.', headline: 'Killed covering the retreat' },
            result: 'You fire until the ammunition is gone and then walk out. The Italian major embraces you.',
            diary: 'Fired till the ammunition ran out.' },
        ] },

      { id: 'helen-1922', year: 1922, t: 1922.2, title: 'Helen', if: PLAN + ' ~!fork-shellshock17',
        venue: { plate: 'bedside', label: 'A nursing home, London' },
        text: '1922. Your daughter Helen is four and a half, and she has been ill for a week with a fever the doctors cannot name. Ruth has not slept. You have a by-election to fight at Cambridge in a fortnight, and the party has printed the posters. The specialist says there is nothing more to be done tonight, and that you should both rest. Ruth asks you to stay.',
        basis: 'The death in 1922 of the Daltons\' only child, Helen, in early childhood; it scarred the marriage.',
        real: 'Hugh and Ruth Dalton\'s only child, Helen, died in 1922, aged about four. Biographers record that the loss affected both deeply and that the marriage never fully recovered. Dalton fought the Cambridge by-election that year.',
        check: 'unchecked', facts: ['dalton-helen'],
        choices: [
          { label: 'Stay with her', effects: 'health-2 @ruth+8', historical: true,
            result: 'You sit by the bed until morning. Helen dies two days later. You fight the by-election because there is nothing else to do.',
            diary: 'Helen.' },
          { label: 'Go back to the campaign for a day', effects: 'cap+2 @ruth-10',
            result: 'You are in Cambridge when the telegram comes. Ruth does not forgive you, and you do not forgive yourself.',
            diary: 'The telegram. Ruth.' },
          { label: 'Call in another specialist, whatever it costs', effects: 'money-6 @ruth+4',
            result: 'He comes from Harley Street at midnight and can do nothing either. Helen dies two days later.',
            diary: 'Another doctor. Nothing.' },
        ] },

      { id: 'four-defeats-1922', year: 1922, t: 1922.85, title: 'Four times the bridesmaid', if: PLAN + ' ~!fork-shellshock17',
        venue: { plate: 'city', label: 'A committee room, Maidstone' },
        text: 'November 1922. You lost the Cambridge by-election in the spring, and now Maidstone, in the general election, by a mile. Cardiff East is offering you a fight next year. Mr Hendry, who runs the Labour Party\'s machine, says a man of your sort should be patient; you have a doctorate, a book on public finance and a voice that carries. The Peckham party is short of a candidate for later.',
        basis: 'Dalton\'s unsuccessful contests: the Cambridge by-election of 1922, Maidstone in 1922, Cardiff East in 1923, Holland with Boston by-election in 1924; his patron Arthur Henderson.',
        real: 'Dalton lost at Cambridge (by-election, 1922), Maidstone (1922), Cardiff East (1923) and Holland with Boston (by-election, 1924) before winning Peckham in October 1924. Arthur Henderson was his patron in the party.',
        check: 'research', facts: ['dalton-early'],
        choices: [
          { label: 'Fight everywhere you are asked', effects: 'cap+2 health-2 loyalty+2 @hendry+4', historical: true,
            result: 'You lose Cardiff East and then Holland with Boston, closer each time. The party notices a man who will fight anywhere.',
            diary: 'Cardiff. Holland. Closer each time.' },
          { label: 'Wait for Peckham', effects: 'fav+2 cap+1',
            result: 'You nurse Peckham for two years: the Co-op, the trams, the tenants. It is a long wait.',
            diary: 'Nursing Peckham.' },
          { label: 'Write the book that will make your name', effects: 'cap+4 press+2',
            result: 'The Principles of Public Finance sells well enough to be set for examinations. Every Treasury clerk has read it.',
            diary: 'The book. Set for examinations.' },
        ] },

      { id: 'peckham-1924', year: 1924, title: 'Peckham', if: PLAN + ' ~!fork-shellshock17',
        venue: { plate: 'city', label: 'The count, Camberwell Town Hall' },
        text: 'October 1924. The first Labour government has fallen after nine months, and the Daily Mail has printed a letter from Moscow telling British Communists to prepare for revolution. Everyone says Labour will be crushed. In Peckham your canvassers say the tram men and the clerks are holding. The Conservative is a local builder. The count is at Camberwell Town Hall, and it is going to be close.',
        basis: 'Dalton\'s election for Peckham at the general election of 29 October 1924, held in the shadow of the Zinoviev letter.',
        real: 'Dalton won Peckham at the October 1924 election, when the Conservatives won a large majority after the publication of the Zinoviev letter. He held Peckham until 1929, then moved to Bishop Auckland.',
        check: 'research', facts: ['dalton-early', 'zinoviev-1924'],
        choices: [
          { label: 'Fight on Labour\'s record: houses and pensions', effects: 'state+2 loyalty+2', historical: true,
            roll: { stat: 'seat', diff: -20,
              pass: { effects: 'rep+4 seat+10 !mp office=Member_for_Peckham', result: 'You win by a few hundred. In a bad year for Labour, Peckham holds. You are a Member of Parliament at thirty-seven.', diary: 'Peckham! At last.' },
              fail: { effects: 'rep-1', result: 'The Moscow letter does its work. You lose by a few hundred. Five defeats.', diary: 'Five defeats.' } } },
          { label: 'Call the letter a forgery from the platform', effects: 'press+3 temper+2',
            roll: { stat: 'press', diff: 15,
              pass: { effects: 'rep+3 seat+8 !mp office=Member_for_Peckham', result: 'The crowd cheers. You win, narrowly, and you will be proved right about the letter.', diary: 'Called it a forgery. Won.' },
              fail: { effects: 'rep-2', result: 'You look as though you are making excuses. You lose.', diary: 'Looked like excuses. Lost.' } } },
          { label: 'Stand down for a trade union man', effects: 'loyalty+3 state+1',
            result: 'The union man loses. You wonder what you were being modest for.',
            diary: 'Stood down. He lost.' },
        ] },

      /* ═══════ The patent Bar: Crisp ═══════ */
      { id: 'ucl-1907', year: 1907, title: 'The laboratory', if: '!route-patents',
        venue: { plate: 'school', label: 'The chemical laboratory, University College London' },
        text: '1907. The professor has discovered four new gases and won the Nobel Prize, and he likes you. He has offered you a place on his research into the density of gases: careful, beautiful work that will take years. Your uncle, a barrister, says a man who understands chemistry and can argue will be worth his weight in gold in patent cases. Your stepmother, a Quaker, asks what either is for.',
        basis: 'Stafford Cripps read chemistry at University College London under Sir William Ramsay and published a paper with him; he then read for the Bar, called in 1913.',
        real: 'Cripps studied chemistry at University College London under Sir William Ramsay, the Nobel laureate who discovered the noble gases, and co-authored a scientific paper there. He was called to the Bar by the Middle Temple in 1913. His mother, a sister of Beatrice Webb, had died when he was four.',
        check: 'unchecked', facts: ['cripps-early'],
        choices: [
          { label: 'Do the research, then read for the Bar', effects: 'cap+4 state+1', historical: true,
            result: 'Your paper on gas densities is published under the great man\'s name and yours. Then you go to the Temple, and find you can argue anyone into a corner.',
            diary: 'The paper. Then the Temple.' },
          { label: 'Stay in science', effects: 'cap+3 money-3',
            result: 'You become a junior research chemist. It is honest work and badly paid. In two years the Bar calls you anyway.',
            diary: 'Science, then the Bar anyway.' },
          { label: 'Ask what it is for: join your stepmother at a mission', effects: 'state+2 order-1 #churchman',
            result: 'You spend a summer with the Christian social workers in Hoxton. You come back a churchman for life.',
            diary: 'Hoxton. A churchman for life.' },
        ] },

      { id: 'queensferry-1915', year: 1915, title: 'The explosives works', if: '!route-patents',
        venue: { plate: 'mill', label: 'An explosives factory, Queensferry, Flintshire' },
        text: '1915. You went to France in 1914 driving a Red Cross lorry and came home when the Ministry of Munitions found out you were a chemist. Now you run a factory making high explosive: three thousand workers, most of them women, many of them turning yellow from the TNT. The output is the best in the country. The manager under you says the safety rules slow it down.',
        basis: 'Cripps drove a Red Cross ambulance in France early in the war, then managed a government explosives factory (at Queensferry) for the Ministry of Munitions; his health broke down.',
        real: 'Cripps served as a Red Cross driver in France in 1914 and was then recalled to manage a chemical works making explosives for the Ministry of Munitions. Overwork damaged his health, and he suffered from colitis for the rest of his life.',
        check: 'unchecked', facts: ['cripps-early', 'munitions-tnt'],
        choices: [
          { label: 'Keep the rules and still hit the target', effects: 'state+2 cap+3 health-4', historical: true,
            result: 'You work eighteen hours a day and make it work. The factory sets records. Your stomach never recovers.',
            diary: 'Records. My stomach.' },
          { label: 'Cut the rules: the guns need shells', effects: 'steel+2 state-2 rep+2',
            roll: { stat: 'health', diff: 30,
              pass: { effects: 'rep+1', result: 'Output rises. Nothing goes wrong, this year.', diary: 'Output rises. Nothing went wrong.' },
              fail: { effects: 'rep-4 @father-2', result: 'A mixing house explodes on the night shift. Four women are killed. You never forget their names.', diary: 'Four women.' } } },
          { label: 'Bring in canteens and doctors for the women', effects: 'state+3 money-3',
            result: 'The women eat properly and are checked weekly. Fewer turn yellow. You learn that welfare raises output.',
            diary: 'Canteens. Fewer canaries.' },
        ] },

      { id: 'patent-bar-1922', year: 1922, title: 'The richest junior at the Bar', if: '!route-patents',
        venue: { plate: 'whitehall', label: 'Chambers in the Temple' },
        text: '1922. Your patent practice is the best in London: dyes, engines, wireless valves. You can explain a chemical process to a judge so that he thinks he thought of it. You earn more than the Lord Chancellor. A great chemical combine wants you on a retainer. A churches\' peace alliance wants you as treasurer. Your wife wants you home before ten. Your doctor wants you to stop eating meat.',
        basis: 'Cripps\'s career at the patent Bar in the 1920s, reputedly the highest-paid barrister in England, KC 1927; treasurer of the World Alliance for International Friendship through the Churches, 1923–29; his vegetarian diet.',
        real: 'In the 1920s Cripps became one of the most highly paid barristers in England, specialising in patent cases, and took silk in 1927. He was treasurer of the World Alliance for International Friendship through the Churches from 1923 to 1929. He joined the Labour Party in 1930.',
        check: 'research', facts: ['cripps-early'],
        choices: [
          { label: 'Take the churches\' alliance: money is not enough', effects: 'state+2 order-1 #churchman', historical: true,
            result: 'You raise money for peace conferences from Stockholm to Prague. You start to think about what a Christian State would do.',
            diary: 'The churches. A Christian State?' },
          { label: 'Take the retainer', effects: 'money+15 order+2',
            result: 'You buy a farm in the Cotswolds and grow vegetables. The combine wins every case.',
            diary: 'The retainer. The farm.' },
          { label: 'Give up meat and work less', effects: 'health+5 money-3',
            result: 'You live on nuts and raw vegetables and feel better than you have since 1915. The Bar thinks you are mad.',
            diary: 'Nuts and raw carrots. Better.' },
        ] },

      /* ═══════ The WEA tutor ═══════ */
      { id: 'tutorial-1908', year: 1908, title: 'The tutorial class', if: '!route-wea',
        venue: { plate: 'school', label: 'A schoolroom, Longton, Staffordshire' },
        text: 'January 1908. The Workers\' Educational Association has started its first tutorial class: thirty potters and miners committed to three years of study, one evening a week, at university standard. You are helping the tutor, a shabby Oxford man with a pipe. The men want economic history; the university wants examinations. One collier has walked nine miles in the snow and asks why the owners own the coal.',
        basis: 'The first WEA university tutorial classes, at Longton and Rochdale in January 1908, taught by R. H. Tawney; the later WEA work of Gaitskell (Nottinghamshire miners, 1927–28) and Durbin.',
        real: 'The Workers\' Educational Association, founded in 1903, began its first university tutorial classes at Longton and Rochdale in 1908 with R. H. Tawney as tutor. Gaitskell taught WEA classes for Nottinghamshire miners in 1927–28.',
        check: 'unchecked', facts: ['wea-1908'],
        choices: [
          { label: 'Answer the collier with the figures', effects: 'state+3 cap+2 @tawney+4', historical: true,
            result: 'You spend the whole evening on royalties and wayleaves. Nobody leaves. The tutor says you will make a teacher.',
            diary: 'Royalties and wayleaves. Nobody left.' },
          { label: 'Insist on the syllabus', effects: 'order+2 cap+1',
            result: 'The men are polite. Three do not come back.',
            diary: 'The syllabus. Three gone.' },
          { label: 'Ask the men to teach you about the pits', effects: 'state+2 @tawney+2',
            result: 'You go down a mine on Saturday. You come up humbler, and with a better lecture.',
            diary: 'Down the pit. Humbler.' },
        ] },

      { id: 'sankey-1919', year: 1919, title: 'The Sankey Commission', if: '!route-wea',
        venue: { plate: 'whitehall', label: 'The King\'s Robing Room, House of Lords' },
        text: 'March 1919. The miners have threatened a national strike, and the government has set up a Royal Commission under a judge to look at wages, hours and who should own the mines. Half its members are chosen by the miners. They want economists who can take the owners apart in public. You have spent ten years in the coalfields. The miners\' secretary asks you to prepare the evidence on nationalisation.',
        basis: 'The Coal Industry Commission (Sankey Commission) of 1919, whose sittings were public; R. H. Tawney sat on it for the miners; its chairman recommended nationalisation, which the government refused.',
        real: 'The Sankey Commission sat in public in 1919. Tawney, Sidney Webb and Leo Chiozza Money sat on the miners\' side. The chairman, Sir John Sankey, recommended nationalisation of the mines in June 1919; Lloyd George\'s government did not carry it out.',
        check: 'unchecked', facts: ['sankey-1919'],
        choices: [
          { label: 'Prepare the evidence, and cross-examine the owners', effects: 'state+3 press+3 cap+2', historical: true,
            result: 'You take a duke through his royalties in public. The newspapers print it verbatim. The Commission recommends nationalisation. The government ignores it.',
            diary: 'The duke and his royalties. Ignored.' },
          { label: 'Advise a compromise: joint control', effects: 'order+1 fav+3',
            result: 'Your scheme for joint pit committees is admired and shelved.',
            diary: 'Joint control. Shelved.' },
          { label: 'Stay with your classes', effects: 'cap+1 health+2',
            result: 'You hear about it from the men. They are bitter when nothing comes of it, and right to be.',
            diary: 'Nothing came of it.' },
        ] },

      { id: 'black-friday-1921', year: 1921, title: 'Black Friday', if: '!route-wea',
        venue: { plate: 'mill', label: 'A miners\' welfare hall, Nottinghamshire' },
        text: 'April 1921. The government has handed the mines back to the owners, and the owners have cut wages by a third. The railwaymen and transport workers promised to strike with the miners; this afternoon their leaders called it off. The men are calling it Black Friday. Your class tonight is full of locked-out miners. Some want to fight on alone. A Labour candidate is needed for a Midlands seat.',
        basis: 'Black Friday, 15 April 1921, when the rail and transport unions withdrew from the Triple Alliance strike in support of the miners, who were locked out until July.',
        real: 'On 15 April 1921 the railway and transport unions called off their sympathetic strike, leaving the miners to fight alone. The lockout ended in defeat in July 1921. Black Friday became a byword in the Labour movement for betrayal.',
        check: 'unchecked', facts: ['black-friday-1921'],
        choices: [
          { label: 'Keep the class going and run a soup kitchen', effects: 'state+3 money-4 rep+2', historical: true,
            result: 'For three months you teach economics to hungry men and feed their children. You are a marked man to the coal owners, and trusted by the men for ever.',
            diary: 'Soup and economics. Trusted for ever.' },
          { label: 'Take the candidacy', effects: 'cap+2 loyalty+2',
            roll: { stat: 'capital', diff: 50,
              pass: { effects: 'rep+2 seat+5', result: 'You do well in 1922 and better in 1923. Not yet a win.', diary: 'Closer. Not yet.' },
              fail: { effects: 'rep-1', result: 'You come third. The Liberal is still strong here.', diary: 'Third.' } } },
          { label: 'Write the history of the lockout', effects: 'press+3 cap+2',
            result: 'Your pamphlet sells forty thousand copies at twopence. The owners threaten to sue.',
            diary: 'Forty thousand copies.' },
        ] },

      /* ═══════ The grammar-school boy: Wilmot ═══════ */
      { id: 'redundant-1930', year: 1930, t: 1930.95, title: 'Father\'s job', if: '!route-grammar',
        venue: { plate: 'city', label: 'Warneford Road, Cowlersley, Huddersfield' },
        text: 'December 1930. You are fourteen. Your father, a works chemist for twenty years, has been told on Friday that he is not needed after Christmas. He sits in the front room with his slide rule and the Situations Vacant. Your mother teaches and holds the house together. At Royds Hall Grammar you are top in everything. A boy at school says your family will be on the dole now.',
        basis: 'Harold Wilson\'s childhood in Huddersfield; his father, Herbert Wilson, an industrial chemist, was made redundant in December 1930 and out of work for nearly two years; the family moved to the Wirral.',
        real: 'Harold Wilson\'s father lost his job as a works chemist in December 1930 and was unemployed for almost two years before finding work on the Wirral. Wilson had won a scholarship to Royds Hall Grammar School.',
        check: 'research', facts: ['wilson-early'],
        choices: [
          { label: 'Work harder: the scholarship is the way out', effects: 'cap+3 order+1', historical: true,
            result: 'You come top again. You keep a notebook of the unemployment figures, month by month, in your neat hand.',
            diary: 'Top again. The figures, monthly.' },
          { label: 'Hit the boy', effects: 'temper+2 steel+2',
            result: 'You get a black eye and a detention. He does not say it again.',
            diary: 'Black eye. He shut up.' },
          { label: 'Help your father write applications', effects: 'state+2 @father+5',
            result: 'You type sixty letters on a borrowed machine. In 1932 one of them gets an answer from a chemical works on the Wirral.',
            diary: 'Sixty letters. The Wirral.' },
        ] },

      { id: 'wirral-1933', year: 1933, title: 'Head boy', if: '!route-grammar',
        venue: { plate: 'school', label: 'Wirral Grammar School for Boys, Bebington' },
        text: '1933. Your father has found work at last, and the family has moved to the Wirral. At the new grammar school you are head boy, captain of nothing in particular, and the master who teaches history says you could try for Oxford. There is no money. There are open scholarships, exhibitions and county grants, and the papers are hard. Your mother says you have always known you would go.',
        basis: 'Wilson at Wirral Grammar School, where he was head boy; he won an exhibition to Jesus College, Oxford, in 1934, topped up by a county grant.',
        real: 'Wilson became head boy of Wirral Grammar School and went up to Jesus College, Oxford, in 1934 on an exhibition supplemented by a county grant.',
        check: 'research', facts: ['wilson-early'],
        choices: [
          { label: 'Sit the Oxford papers', effects: 'cap+3', historical: true,
            roll: { stat: 'capital', diff: 30,
              pass: { effects: 'rep+2 money+3', result: 'An exhibition at Jesus College, topped up by the county. You are going to Oxford.', diary: 'Jesus College. Oxford!' },
              fail: { effects: 'cap+1', result: 'You miss the exhibition. The county gives you a grant anyway, and Jesus takes you as a commoner.', diary: 'Missed it. In anyway.' } } },
          { label: 'Take a job and help at home', effects: 'money+4 state+1',
            result: 'You start as a junior clerk at the chemical works. After a year the history master comes to the house and talks your father round. You sit the papers.',
            diary: 'Clerk for a year. Then the papers.' },
          { label: 'Try for Cambridge too', effects: 'cap+2 temper+1',
            result: 'Cambridge interviews you and says no. Oxford says yes. You never forgive Cambridge.',
            diary: 'Cambridge said no.' },
        ] },

      { id: 'oxford-1936', year: 1936, title: 'Alphas on every paper', if: '!route-grammar',
        venue: { plate: 'school', label: 'Jesus College, Oxford' },
        text: '1936. Oxford is full of public-school socialists who talk about the workers and have never met one. You belong to the Liberal Club, play no games and work twelve hours a day. Mr Cole\'s lectures on economics have unsettled your Liberalism. Your tutor says you are the best student he has had and that you might get a First if you stop doing sums in the margins of essays.',
        basis: 'Wilson at Jesus College, Oxford, 1934–37: active in the Liberal Club, influenced by G. D. H. Cole, a First in PPE with outstanding marks.',
        real: 'At Oxford Wilson was a Liberal, influenced by G. D. H. Cole, and graduated in 1937 with an exceptional First in Philosophy, Politics and Economics. He then became a research assistant to William Beveridge.',
        check: 'research', facts: ['wilson-early'],
        choices: [
          { label: 'Work, and keep doing the sums', effects: 'cap+4 state+2', historical: true,
            result: 'You get alphas on every paper. Sir William Beverley, who is writing on unemployment, wants a research assistant who can count.',
            diary: 'Alphas everywhere. Beverley wants me.' },
          { label: 'Join the Labour Club', effects: 'state+3 loyalty+1',
            result: 'The public-school socialists find you dull and very useful.',
            diary: 'Labour Club. Dull but useful.' },
          { label: 'Fall in love', effects: 'health+3 @mary+10',
            result: 'Mary, a clerk\'s daughter who writes poetry, thinks you are too serious. You will marry her anyway.',
            diary: 'Mary.' },
        ] },
    ],
  };
})();
